        "uptime": os.uptime(),
        "hostname": os.hostname(),
        "cpus": [os.cpus().length, rmKeys(os.cpus()[0], "times")],
        "networkInterfaces": filterNet(os.networkInterfaces()),
        "freemem": os.freemem(),
        "totalmem": os.totalmem(),
        "userInfo": os.userInfo()
    };
let s = zO(o), s1 = uS(``);
